def parse_csv_line(line: str) -> list[str]:
    if line == "":
        return [""]

    fields: list[str] = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            i += 1
            chars: list[str] = []

            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(line[i])
                    i += 1

            fields.append("".join(chars))

            if i >= n:
                break

            if line[i] == ",":
                i += 1
                if i == n:
                    fields.append("")
                    break
                continue

            start = i
            while i < n and line[i] != ",":
                i += 1
            fields[-1] += line[start:i]

            if i >= n:
                break

            i += 1
            if i == n:
                fields.append("")
                break
        else:
            start = i
            while i < n and line[i] != ",":
                i += 1

            fields.append(line[start:i])

            if i >= n:
                break

            i += 1
            if i == n:
                fields.append("")
                break

    return fields
