def flatten(obj: dict, sep: str = ".") -> dict:
    result = {}
    if not obj:
        return result

    def walk(value, key):
        if isinstance(value, dict):
            if not value:
                result[key] = {}
                return
            for k, v in value.items():
                nk = f"{key}{sep}{k}" if key is not None else str(k)
                walk(v, nk)
        elif isinstance(value, list):
            if not value:
                result[key] = []
                return
            for i, v in enumerate(value):
                nk = f"{key}{sep}{i}" if key is not None else str(i)
                walk(v, nk)
        else:
            result[key] = value

    for k, v in obj.items():
        walk(v, str(k))
    return result
