def flatten(obj: dict, sep: str = ".") -> dict:
    result = {}

    def _flatten(value, prefix):
        if isinstance(value, dict):
            if not value:
                if prefix is not None:
                    result[prefix] = value
                return
            for key, child in value.items():
                key_part = str(key)
                new_prefix = key_part if prefix is None else f"{prefix}{sep}{key_part}"
                _flatten(child, new_prefix)
        elif isinstance(value, list):
            if not value:
                if prefix is not None:
                    result[prefix] = value
                return
            for index, child in enumerate(value):
                key_part = str(index)
                new_prefix = key_part if prefix is None else f"{prefix}{sep}{key_part}"
                _flatten(child, new_prefix)
        else:
            if prefix is not None:
                result[prefix] = value

    _flatten(obj, None)
    return result
