def is_valid_ipv4(s: str) -> bool:
    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if not part or len(part) > 3:
            return False

        if any(c < "0" or c > "9" for c in part):
            return False

        if len(part) > 1 and part[0] == "0":
            return False

        if int(part) > 255:
            return False

    return True
