from collections import Counter

def top_words(text: str, k: int) -> list[tuple[str, int]]:
    counts = Counter()
    chars = []

    for ch in text:
        if ch.isalpha():
            chars.append(ch)
        elif chars:
            counts["".join(chars).lower()] += 1
            chars.clear()

    if chars:
        counts["".join(chars).lower()] += 1

    if k <= 0:
        return []

    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))[:k]
