def moving_average(xs, k):
    if k <= 0 or k > len(xs):
        raise ValueError("k must be between 1 and len(xs)")
    out = []
    for i in range(len(xs) - k + 1):
        out.append(sum(xs[i:i + k]) / k)
    return out
